    internal static void Validate(ContractWorld w){var s=w.Treaties?.Supply;if(s==null)return;Need(s.Schema==1&&s.Policy==Policy&&s.Entries!=null&&s.Papers!=null&&s.Openings!=null&&s.Failures!=null&&s.Entries.Select(e=>e.Input.Id).Distinct().Count()==s.Entries.Length&&s.Papers.Select(p=>p.Id).Distinct().Count()==s.Papers.Length&&s.Openings.Select(o=>o.Message).Distinct().Count()==s.Openings.Length,"実物補給の原本が不正です");foreach(var e in s.Entries){Need(e.At<=w.ElapsedSeconds&&e.Revision>0&&e.Revision<=w.CommitSequence&&!FactionStances.OtherIdUsed(w,e.Input.Id,includeTreatySupply:false)&&!FactionStances.OwnIdUsed(w,e.Input.Id)&&Prepare(w,e.Input,e.Actor,e.At,e.Revision)==e,"供与在庫・所在・権限・数量の根拠が違います");if(e.Paper!=null)Need(s.Papers.Contains(Paper(w,e)),"供与手配の書状が違います");}foreach(var p in s.Papers){Need(w.Messaging.Messages.Contains(Envelope(p))&&w.SealedMessages.Contains(new(p.Id)),"供与封書の原文が違います");foreach(var c in w.Couriers!.Missions.Where(c=>w.Messaging.Attempts.Any(a=>a.Id==c.Attempt&&a.MessageId==p.Id)))Need(c.Destination==NewGameWorld.Node(p.Address.Value),"供与の宛先を現在地へすり替えています");Need(MessageFlow.Knows(w.Messaging,p.Id,p.Recipient.Value)==s.Openings.Any(o=>o.Message==p.Id),"供与の未開封内容を知っています");}foreach(var o in s.Openings){var p=s.Papers.Single(p=>p.Id==o.Message);Need(o.Actor==p.Recipient&&o.At<=w.ElapsedSeconds&&o.Revision>p.Revision&&o.Revision<=w.CommitSequence&&MessageFlow.LearnedAt(w.Messaging,p.Id,o.Actor.Value)==o.At&&w.Messaging.Attempts.Any(a=>a.MessageId==p.Id&&a.ReceiverId==o.Actor.Value&&a.Status==AttemptStatus.Delivered&&a.FinishedAt<=o.At),"供与書状の本人開封ではありません");}Need(s.Failures.Select(o=>o.Message).Distinct().Count()==s.Failures.Length,"供与不達の認識が重複しています");foreach(var o in s.Failures){var m=w.Messaging.Messages.Single(m=>m.Id==o.Message);Need(m.Kind=="delivery-failure"&&m.RecipientId==o.Actor.Value&&o.At<=w.ElapsedSeconds&&o.Revision>0&&o.Revision<=w.CommitSequence&&MessageFlow.LearnedAt(w.Messaging,m.Id,o.Actor.Value)==o.At&&s.Papers.Any(p=>w.Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id))&&w.Messaging.Attempts.Any(a=>a.MessageId==m.Id&&a.ReceiverId==o.Actor.Value&&a.Status==AttemptStatus.Delivered&&a.FinishedAt<=o.At),"実際の供与不達の本人認識ではありません");}Need(w.Messaging.Messages.Count(m=>m.Kind==Kind)==s.Papers.Length,"供与封書の数が違います");foreach(var a in s.Entries.Where(e=>e.Input.Action==TreatySupplyAction.Arrange))Need(Cargo(w,a.Root)>=0,"預かり米が負になっています");long transfers=CommunityEconomy.SitesFor(w).Sum(site=>HouseTransfers(w,site,w.ElapsedSeconds,w.CommitSequence+1).Sum(e=>e.Amount));Need(transfers+s.Entries.Where(e=>e.Input.Action==TreatySupplyAction.Arrange).Sum(e=>Cargo(w,e.Root))==0,"供与の倉・携行米が保存則に一致しません");}
}
public sealed partial class WorldSession
{
    internal void AutoTreatySupply(TreatySupplyInput i,EntityId actor){lock(gate)Change(w=>TreatySupply.Automatic(w,i,actor));}
    public CommandResult ManageTreatySupply(TreatySupplyInput i,EntityId actor,long revision){lock(gate){if(actor!=state.PlayerControl||i.Action is TreatySupplyAction.Grant or TreatySupplyAction.Refuse)return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,"本人の実物受取操作ではありません");var old=state.Treaties?.Supply?.Entries.SingleOrDefault(e=>e.Input.Id==i.Id);if(old!=null)return new(old.Input==i?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"受付済みです");if(FactionStances.OtherIdUsed(state,i.Id)||FactionStances.OwnIdUsed(state,i.Id))return new(ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"別の原本です");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");try{Change(w=>TreatySupply.Apply(w,i,actor));TreatySupply.TakeTurns(this);return new(ResultCode.Accepted,i.Id,state.CommitSequence,"実物補給の手配・受取・納入を記録しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
